      // Procedural bamboo texture
      function makeBambooTexture() {
        const canvas = document.createElement("canvas");
        canvas.width = 256;
        canvas.height = 256;
        const ctx = canvas.getContext("2d");

        ctx.fillStyle = "#c99548";
        ctx.fillRect(0, 0, 256, 256);

        let seed = 9137;
        const random = () => {
          seed = (seed * 16807) % 2147483647;
          return (seed - 1) / 2147483646;
        };

        for (let i = 0; i < 110; i++) {
          const x = random() * 256;
          const width = 0.4 + random() * 1.8;
          const alpha = 0.025 + random() * 0.09;

          ctx.strokeStyle = `rgba(83, 48, 17, ${alpha})`;
          ctx.lineWidth = width;
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.bezierCurveTo(
            x + random() * 8 - 4,
            80,
            x + random() * 10 - 5,
            170,
            x + random() * 5 - 2.5,
            256
          );
          ctx.stroke();
        }

        for (let i = 0; i < 7; i++) {
          const x = random() * 256;
          const y = random() * 256;
          const radius = 5 + random() * 13;

          ctx.strokeStyle = "rgba(91, 52, 20, 0.14)";
          ctx.lineWidth = 1.4;
          ctx.beginPath();
          ctx.ellipse(x, y, radius * 1.8, radius, 0, 0, Math.PI * 2);
          ctx.stroke();
        }

        const texture = new THREE.CanvasTexture(canvas);
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(2, 1);
        texture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
        return texture;
      }

      const bambooTexture = makeBambooTexture();

      const bambooMaterial = new THREE.MeshStandardMaterial({
        color: 0xf1c47a,
        map: bambooTexture,
        roughness: 0.68,
        metalness: 0
      });

      const bindingMaterial = new THREE.MeshStandardMaterial({
        color: 0x4a3826,
        roughness: 0.82
      });

      const stringMaterial = new THREE.MeshStandardMaterial({
        color: 0x493b2d,
        roughness: 0.95
      });

      const kiteGroup = new THREE.Group();
