      scene.add(kiteGroup);

      // Creates a rectangular bamboo beam between two points.
      function addBeam(a, b, width, depth, material = bambooMaterial) {
        const start = new THREE.Vector3(...a);
        const end = new THREE.Vector3(...b);
        const direction = end.clone().sub(start);
        const length = direction.length();

        const geometry = new THREE.BoxGeometry(width, length, depth);
        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.copy(start).add(end).multiplyScalar(0.5);
        mesh.quaternion.setFromUnitVectors(
          new THREE.Vector3(0, 1, 0),
          direction.normalize()
        );
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        kiteGroup.add(mesh);
        return mesh;
      }

      // Main rectangular bamboo perimeter
      const halfWidth = 2.72;
      const halfHeight = 1.8;
      const frontZ = 0.18;
      const backZ = -0.18;

      for (const z of [frontZ, backZ]) {
        addBeam(
          [-halfWidth, -halfHeight, z],
          [-halfWidth, halfHeight, z],
          0.115,
          0.12
        );
        addBeam(
          [halfWidth, -halfHeight, z],
          [halfWidth, halfHeight, z],
          0.115,
          0.12
        );
        addBeam(
          [-halfWidth, halfHeight, z],
          [halfWidth, halfHeight, z],
          0.115,
          0.12
        );
      }

      // Crossed internal bamboo ribs
      addBeam(
        [-2.56, -1.64, 0],
        [2.56, 1.64, 0],
        0.105,
        0.105
      );
      addBeam(
        [2.56, -1.64, 0],
        [-2.56, 1.64, 0],
        0.105,
        0.105
      );

      // Short depth braces at the four corners
      for (const x of [-halfWidth, halfWidth]) {
        for (const y of [-halfHeight, halfHeight]) {
          addBeam(
            [x, y, backZ],
            [x, y, frontZ],
            0.075,
            0.075
          );
        }
      }

      // Dark bindings around the frame corners and rib intersections
      const bindingGeometry = new THREE.TorusGeometry(0.135, 0.024, 8, 24);

      for (const x of [-halfWidth, halfWidth]) {
        for (const y of [-halfHeight, halfHeight]) {
          const binding = new THREE.Mesh(bindingGeometry, bindingMaterial);
          binding.position.set(x, y, 0);
          binding.castShadow = true;
          kiteGroup.add(binding);
        }
      }

      for (const x of [-2.56, 2.56]) {
        for (const y of [-1.64, 1.64]) {
          const binding = new THREE.Mesh(bindingGeometry, bindingMaterial);
          binding.position.set(x, y, 0);
          binding.castShadow = true;
          kiteGroup.add(binding);
        }
      }

      // Central hub
      const hub = new THREE.Mesh(
        new THREE.CylinderGeometry(0.13, 0.13, 0.3, 20),
        bindingMaterial
      );
      hub.rotation.x = Math.PI / 2;
      hub.position.set(0, 0, 0.28);
      hub.castShadow = true;
      kiteGroup.add(hub);

      // Fine string helper
      function addString(a, b, radius = 0.009, material = stringMaterial) {
        const curve = new THREE.LineCurve3(
          new THREE.Vector3(...a),
          new THREE.Vector3(...b)
        );
        const geometry = new THREE.TubeGeometry(curve, 18, radius, 5, false);
        const mesh = new THREE.Mesh(geometry, material);
        mesh.castShadow = true;
        kiteGroup.add(mesh);
        return mesh;
      }

      const hubPoint = new THREE.Vector3(0, 0, 0.39);

      // Four corner lines converge at the hub
      addString([-halfWidth, -halfHeight, 0.25], hubPoint, 0.011);
      addString([halfWidth, -halfHeight, 0.25], hubPoint, 0.011);
      addString([-halfWidth, halfHeight, 0.25], hubPoint, 0.011);
      addString([halfWidth, halfHeight, 0.25], hubPoint, 0.011);

      // Main tail line
      addString([0, 0, 0.39], [0, -4.35, 0.22], 0.012);

      // Secondary lines from the upper corners to the tail
      addString([-halfWidth, halfHeight, 0.25], [0, -4.28, 0.22], 0.007);
      addString([halfWidth, halfHeight, 0.25], [0, -4.28, 0.22], 0.007);

      // Tapered, striped linen tail
      function createTail() {
        const segments = 14;
        const positions = [];
        const colors = [];
        const indices = [];

        const red = new THREE.Color(0xa94732);
        const cream = new THREE.Color(0xe4c995);
        const tip = new THREE.Color(0x7f3028);

        for (let i = 0; i <= segments; i++) {
          const t = i / segments;
          const y = -4.35 - t * 2.75;
          const halfWidth = 0.39 - t * 0.31;
          const z = t > 0.82 ? -0.055 : 0.045;

          positions.push(
            -halfWidth, y, z,
             halfWidth, y, z,
            -halfWidth, y, z + 0.07,
             halfWidth, y, z + 0.07
          );

          const color = red.clone().lerp(cream, t * 0.58);
          if (t > 0.84) {
            color.lerp(tip, (t - 0.84) / 0.16 * 0.7);
          }

          for (let j = 0; j < 4; j++) {
            colors.push(color, color, color, color);
          }
        }

        for (let i = 0; i < segments; i++) {
          const a = i * 4;
          const b = (i + 1) * 4;

          // Front and back faces
          indices.push(a, a + 1, b + 1, a, b + 1, b);
          indices.push(a + 2, b + 2, a + 3, a + 3, b + 2, b + 3);

          // Side faces
          indices.push(a, b, b + 1, a, b + 1, a + 1);
          indices.push(a + 2, a + 3, b + 3, a + 2, b + 3, b + 2);
        }

        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute(
          "position",
          new THREE.Float32BufferAttribute(positions, 3)
        );
        geometry.setAttribute(
          "color",
          new THREE.Float32BufferAttribute(colors, 3)
        );
        geometry.setIndex(indices);
        geometry.computeVertexNormals();

        const material = new THREE.MeshStandardMaterial({
          vertexColors: true,
          roughness: 0.92,
          side: THREE.DoubleSide
        });

        const tail = new THREE.Mesh(geometry, material);
        tail.castShadow = true;
        tail.receiveShadow = true;
        kiteGroup.add(tail);

        // Binding at the tail end
        const tailBinding = new THREE.Mesh(
          new THREE.TorusGeometry(0.105, 0.022, 8, 20),
          bindingMaterial
        );
        tailBinding.position.set(0, -7.1, 0);
        tailBinding.rotation.x = Math.PI / 2;
        tailBinding.castShadow = true;
        kiteGroup.add(tailBinding);

        // Small streamers beneath the tail
        addString([-0.2, -5.65, 0.05], [-0.82, -7.02, 0.05], 0.008);
        addString([0.2, -5.65, 0.05], [0.82, -7.02, 0.05], 0.008);
      }

      createTail();

      // Ground
      const ground = new THREE.Mesh(
        new THREE.PlaneGeometry(100, 100),
        new THREE.MeshStandardMaterial({
          color: 0xc7d4c7,
          roughness: 1
        })
      );
      ground.rotation.x = -Math.PI / 2;
      ground.position.y = -7.16;
      ground.receiveShadow = true;
      scene.add(ground);

      // Soft circular patch beneath the kite
      const shadowDisc = new THREE.Mesh(
        new THREE.CircleGeometry(3.4, 64),
        new THREE.MeshBasicMaterial({
          color: 0x52665a,
          transparent: true,
          opacity: 0.08,
          depthWrite: false
        })
      );
      shadowDisc.rotation.x = -Math.PI / 2;
      shadowDisc.position.set(0, -7.145, 0);
      scene.add(shadowDisc);

      // Subtle airborne dust
      const dustCount = 160;
      const dustPositions = new Float32Array(dustCount * 3);

      for (let i = 0; i < dustCount; i++) {
        dustPositions[i * 3] = (Math.random() - 0.5) * 24;
        dustPositions[i * 3 + 1] = Math.random() * 12 - 7;
        dustPositions[i * 3 + 2] = -4 - Math.random() * 12;
      }

      const dustGeometry = new THREE.BufferGeometry();
      dustGeometry.setAttribute(
        "position",
        new THREE.BufferAttribute(dustPositions, 3)
      );

      const dust = new THREE.Points(
        dustGeometry,
        new THREE.PointsMaterial({
          color: 0xfff9df,
          size: 0.035,
          transparent: true,
          opacity: 0.45,
          depthWrite: false
        })
      );
      scene.add(dust);

      // Custom camera controls
      const defaultView = {
        target: new THREE.Vector3(0, -0.35, 0),
        radius: 10.4,
        theta: 0.62,
        phi: 1.13
      };

      const view = {
        target: defaultView.target.clone(),
        radius: defaultView.radius,
        theta: defaultView.theta,
        phi: defaultView.phi
      };

      function updateCamera() {
        const offset = new THREE.Vector3().setFromSphericalCoords(
          view.radius,
          view.phi,
          view.theta
        );

        camera.position.copy(view.target).add(offset);
        camera.lookAt(view.target);
      }

      function resetCamera() {
        view.target.copy(defaultView.target);
        view.radius = defaultView.radius;
        view.theta = defaultView.theta;
        view.phi = defaultView.phi;
        updateCamera();
      }

      updateCamera();

      let dragging = false;
      let lastX = 0;
      let lastY = 0;

      const canvas = renderer.domElement;

      canvas.addEventListener("pointerdown", (event) => {
        dragging = true;
        lastX = event.clientX;
        lastY = event.clientY;
        canvas.setPointerCapture(event.pointerId);
      });

      canvas.addEventListener("pointermove", (event) => {
        if (!dragging) return;

        const dx = event.clientX - lastX;
        const dy = event.clientY - lastY;
        lastX = event.clientX;
        lastY = event.clientY;

        if (event.shiftKey || event.buttons === 2) {
          const right = new THREE.Vector3();
          const up = new THREE.Vector3();
          camera.matrixWorld.extractBasis(right, up, new THREE.Vector3());

          const panScale = view.radius * 0.0012;
          view.target.addScaledVector(right, -dx * panScale);
          view.target.addScaledVector(up, dy * panScale);
        } else {
          view.theta -= dx * 0.006;
          view.phi = THREE.MathUtils.clamp(
            view.phi - dy * 0.005,
            0.22,
            Math.PI - 0.22
          );
        }

        updateCamera();
      });

      function endDrag(event) {
        dragging = false;
        if (event.pointerId !== undefined && canvas.hasPointerCapture(event.pointerId)) {
          canvas.releasePointerCapture(event.pointerId);
        }
      }

      canvas.addEventListener("pointerup", endDrag);
      canvas.addEventListener("pointercancel", endDrag);
      canvas.addEventListener("contextmenu", (event) => event.preventDefault());

      canvas.addEventListener(
        "wheel",
        (event) => {
          event.preventDefault();
          view.radius = THREE.MathUtils.clamp(
            view.radius * Math.exp(event.deltaY * 0.001),
            4.5,
            22
          );
          updateCamera();
        },
        { passive: false }
      );

      canvas.addEventListener("dblclick", resetCamera);

      addEventListener("keydown", (event) => {
        const step = 0.08;

        if (event.key === "ArrowLeft") view.theta += step;
        if (event.key === "ArrowRight") view.theta -= step;
        if (event.key === "ArrowUp") view.phi -= step;
        if (event.key === "ArrowDown") view.phi += step;
        if (event.key === "+" || event.key === "=") view.radius -= 0.5;
        if (event.key === "-" || event.key === "_") view.radius += 0.5;
        if (event.key.toLowerCase() === "r") resetCamera();

        view.phi = THREE.MathUtils.clamp(view.phi, 0.22, Math.PI - 0.22);
        view.radius = THREE.MathUtils.clamp(view.radius, 4.5, 22);
        updateCamera();
      });

      addEventListener("resize", () => {
        camera.aspect = innerWidth / innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(innerWidth, innerHeight);
        renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
      });

      // Gentle breeze animation
      const clock = new THREE.Clock();

      function animate() {
        const time = clock.getElapsedTime();

        kiteGroup.rotation.z = Math.sin(time * 0.58) * 0.035;
        kiteGroup.rotation.x = Math.sin(time * 0.42 + 1.1) * 0.025;
        kiteGroup.rotation.y = Math.sin(time * 0.34) * 0.018;

        dust.rotation.y = time * 0.008;
        dust.position.y = Math.sin(time * 0.18) * 0.12;

        renderer.render(scene, camera);
        requestAnimationFrame(animate);
      }

      animate();
    } catch (error) {
      console.error(error);
      fallback.style.display = "grid";
    }
  </script>
</body>
